/**
 * Test the normal DeadlockInfo behaviour in the
 * absence of deadlocks.
 *
 * DeadlockInfo instantiation reproduces the REEF-588
 * because the NPE was thrown in the DeadlockInfo constructor.
 */
@Test
public void testDeadlockInfoWithDeadlockAbsent() throws NullPointerException {
    final DeadlockInfo deadlockInfo = new DeadlockInfo();
    LOG.log(Level.INFO, ThreadLogger.getFormattedDeadlockInfo("DeadlockInfo test, none deadlocks expected. Deadlocks found: "));
    Assert.assertEquals("DeadlockInfo found deadlocks when none should exist.", 0, deadlockInfo.getDeadlockedThreads().length);
}

