    // Define expected values
    final Map<String, LocalResource> localResourceMap = new HashMap<>();
    final String archiveKey = "archive";
    final String fileKey = "file";
    // Create submission object
    final LocalResource archiveResource = new LocalResource().setResource("archiveResourceLocation").setSize(100).setTimestamp(200).setType(LocalResource.TYPE_ARCHIVE).setVisibility(LocalResource.VISIBILITY_PRIVATE);
