    final Credentials creds = new Credentials().addSecret("secretKey", "secretVal").addToken("tokKey", "tokVal");
    final AmContainerSpec containerSpec = new AmContainerSpec().setCommand("submission command").addLocalResource(archiveKey, archiveResource).addLocalResource(fileKey, fileResource).addEnvironment("envKey", "envVal").addApplicationAcl("aclKey", "aclVal").addServiceData("sdKey", "sdVal").setCredentials(creds);
    final Resource resource = new Resource().setMemory(500).setvCores(600);
    final ApplicationSubmission submission = new ApplicationSubmission().setApplicationType(ApplicationSubmission.DEFAULT_APPLICATION_TYPE).setMaxAppAttempts(ApplicationSubmission.DEFAULT_MAX_APP_ATTEMPTS).setKeepContainers(ApplicationSubmission.DEFAULT_KEEP_CONTAINERS_ACROSS_APPLICATION_ATTEMPTS).setQueue(ApplicationSubmission.DEFAULT_QUEUE).setPriority(ApplicationSubmission.DEFAULT_PRIORITY).setUnmanagedAM(ApplicationSubmission.DEFAULT_UNMANAGED_AM).setAmContainerSpec(containerSpec).setApplicationId("appId").setApplicationName("name").setResource(resource);
    // Json validation
    final ObjectMapper mapper = new ObjectMapper();
    final StringWriter writer = new StringWriter();
    mapper.writeValue(writer, submission);
    final String jsonStr = writer.toString();
    final JsonNode rootJsonNode = mapper.readTree(jsonStr);
    Assert.assertEquals(rootJsonNode.get(Constants.APPLICATION_ID).asText(), submission.getApplicationId());
    Assert.assertEquals(rootJsonNode.get(Constants.APPLICATION_NAME).asText(), submission.getApplicationName());
    Assert.assertEquals(rootJsonNode.get(Constants.MAX_APP_ATTEMPTS).asInt(), submission.getMaxAppAttempts());
