public void testAmShutdown() throws IOException, YarnException {
    Assume.assumeTrue("This test requires a YARN Resource Manager to connect to", Boolean.parseBoolean(System.getenv("REEF_TEST_YARN")));
    final YarnConfiguration yarnConfig = new YarnConfiguration();
    // Start YARN client and register the application
    final YarnClient yarnClient = YarnClient.createYarnClient();
    yarnClient.init(yarnConfig);
    yarnClient.start();
    final ContainerLaunchContext containerContext = Records.newRecord(ContainerLaunchContext.class);
    containerContext.setCommands(Collections.<String>emptyList());
    containerContext.setLocalResources(Collections.<String, LocalResource>emptyMap());
    containerContext.setEnvironment(Collections.<String, String>emptyMap());
    containerContext.setTokens(getTokens());
    final ApplicationSubmissionContext appContext = yarnClient.createApplication().getApplicationSubmissionContext();
    appContext.setApplicationName("REEF_Unmanaged_AM_Test");
    appContext.setAMContainerSpec(containerContext);
    appContext.setUnmanagedAM(true);
    appContext.setQueue("default");
    final ApplicationId applicationId = appContext.getApplicationId();
    LOG.log(Level.INFO, "Registered YARN application: {0}", applicationId);
    yarnClient.submitApplication(appContext);
    LOG.log(Level.INFO, "YARN application submitted: {0}", applicationId);
    addToken(yarnClient.getAMRMToken(applicationId));
    // Start the AM
    final AMRMClientAsync<AMRMClient.ContainerRequest> rmClient = AMRMClientAsync.createAMRMClientAsync(1000, this);
    rmClient.init(yarnConfig);
    rmClient.start();
    final NMClientAsync nmClient = new NMClientAsyncImpl(this);
    nmClient.init(yarnConfig);
    nmClient.start();
    final RegisterApplicationMasterResponse registration = rmClient.registerApplicationMaster(NetUtils.getHostname(), -1, null);
    LOG.log(Level.INFO, "Unmanaged AM is running: {0}", registration);
    rmClient.unregisterApplicationMaster(FinalApplicationStatus.SUCCEEDED, "Success!", null);
    LOG.log(Level.INFO, "Unregistering AM: state {0}", rmClient.getServiceState());
    // Shutdown the AM
    rmClient.stop();
    nmClient.stop();
    // Get the final application report
    final ApplicationReport appReport = yarnClient.getApplicationReport(applicationId);
    final YarnApplicationState appState = appReport.getYarnApplicationState();
    final FinalApplicationStatus finalAttemptStatus = appReport.getFinalApplicationStatus();
    LOG.log(Level.INFO, "Application {0} final attempt {1} status: {2}/{3}", new Object[] { applicationId, appReport.getCurrentApplicationAttemptId(), appState, finalAttemptStatus });
    Assert.assertEquals("Application must be in FINISHED state", YarnApplicationState.FINISHED, appState);
    Assert.assertEquals("Final status must be SUCCEEDED", FinalApplicationStatus.SUCCEEDED, finalAttemptStatus);
    // Shutdown YARN client
    yarnClient.stop();
}

/**
 * Tests whether the amount of memory is transferred correctly.
 */
@Test
public void testDifferentMemory() throws InjectionException {
    final LoggingScopeFactory loggingScopeFactory = Tang.Factory.getTang().newInjector().getInstance(LoggingScopeFactory.class);
    final EvaluatorRequestor evaluatorRequestor = new EvaluatorRequestorImpl(resourceCatalog, resourceRequestHandler, loggingScopeFactory);
    final EvaluatorRequest requestOne = EvaluatorRequest.newBuilder().setNumber(1).setMemory(64).setNumberOfCores(1).build();
    final EvaluatorRequest requestTwo = EvaluatorRequest.newBuilder().setNumber(1).setMemory(128).setNumberOfCores(2).build();
    evaluatorRequestor.submit(requestOne);
    Assert.assertEquals("Request in REEF and YARN form should have the same amount of memory", requestOne.getMegaBytes(), containerRequestHandler.getRequests()[0].getCapability().getMemory());
    evaluatorRequestor.submit(requestTwo);
    Assert.assertEquals("Request in REEF and YARN form should have the same amount of memory", requestTwo.getMegaBytes(), containerRequestHandler.getRequests()[0].getCapability().getMemory());
    evaluatorRequestor.submit(requestOne);
    Assert.assertNotEquals("Second YARN request should have different amount of memory", requestTwo.getMegaBytes(), containerRequestHandler.getRequests()[0].getCapability().getMemory());
}

