    final EStage<TransportEvent> clientStage = new ThreadPoolStage<>("client1", new LoggingEventHandler<TransportEvent>(), 1, new LoggingEventHandler<Throwable>());
    final int msgsSent = 100;
    final ServerHandler serverHandler = new ServerHandler(monitor, msgsSent);
